(() => {
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let liveOwner='',liveData=null,liveAt=0,ownedStatus='upcoming';const live=()=>window.ColorWinOperations&&!window.ColorWinOperations.preview();
  const games={ff:{name:'Free Fire',short:'FF',className:'ff',tag:'SURVIVAL ARENA'},pubg:{name:'PUBG',short:'PUBG',className:'pubg',tag:'BATTLE ARENA'}};
  const matches=[{id:'ff-solo',game:'ff',title:'Free Fire Solo Showdown',mode:'Solo',format:'Battle Royale'},{id:'pubg-squad',game:'pubg',title:'PUBG Squad Showdown',mode:'Squad',format:'Battle Royale'},{id:'ff-squad',game:'ff',title:'Free Fire Squad Clash',mode:'Squad',format:'Team match'},{id:'ff-duo',game:'ff',title:'Free Fire Duo Arena',mode:'Duo',format:'Battle Royale'},{id:'pubg-solo',game:'pubg',title:'PUBG Solo Survival',mode:'Solo',format:'Battle Royale'}];
  const trophy='<img class="cw-trophy" src="assets/icons/golden-trophy.svg" alt="" aria-hidden="true">';
  const arrow='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg>';
  const walletIcon='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 8V5H5a2 2 0 0 0 0 4h15v11H5a2 2 0 0 1-2-2V7"/><path d="M20 12h-6v5h6M16 14.5h1"/></svg>';
  const historyIcon='<img class="tn-history-image" src="assets/icons/match-history.svg" alt="" aria-hidden="true">';
  const header=(title,back='#/account')=>`<header class="tn-header${title==='Tournaments'?' tn-header-root':''}">${title==='Tournaments'?'':`<a href="${back}" aria-label="Go back">‹</a>`}<h1>${title==='Tournaments'?'<span class="tn-brand"><img src="assets/web%20images/color-win-logo-supplied.png" alt="Color Win"><span class="tn-brand-name">TOURNAMENTS</span></span>':title}</h1><a href="#/deposit" class="home-topbar-balance" aria-label="Add funds"><span class="home-balance-value" data-tn-wallet-value>₹—</span><span class="home-balance-add"><img class="home-balance-plus-image" src="assets/web%20images/headerDepositPlus-BYMjCOAj.svg" alt=""></span></a><a href="#/tournaments/my-matches" class="tn-my-icon" aria-label="Match history and rewards">${historyIcon}<small>My matches</small></a></header>`;
  async function loadWallet(page){const owner=window.ColorWinAuth?.session?.user?.id;try{await window.ColorWinAccount.load();if(!page.isConnected||window.ColorWinAuth?.session?.user?.id!==owner)return;const value=Number(window.ColorWinAccount.balance());if(!Number.isFinite(value))throw Error('Invalid balance');page.querySelector('[data-tn-wallet-value]').textContent='₹'+value.toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});}catch{if(page.isConnected&&window.ColorWinAuth?.session?.user?.id===owner){const target=page.querySelector('[data-tn-wallet-value]');if(target){target.textContent='₹—';target.closest('a').title='Balance unavailable. Open Deposit to add funds.';}}}}
  const gameLogo=game=>game==='ff'?'<span class="tn-game-logo tn-logo-ff" aria-label="Free Fire">FREE F<span>I</span>RE</span>':'<span class="tn-game-logo tn-logo-pubg" aria-label="PUBG">PUBG<small>BATTLEGROUNDS</small></span>';
  const banners={'ff-solo':'free-fire-50x-red-prizes.png','ff-squad':'free-fire-100x-purple-prizes.png','ff-duo':'free-fire-10x-green-prizes.png'};
  function card(m){const g=games[m.game],theme=m.id==='ff-squad'?'neon':m.id==='pubg-solo'?'green':'red',boost=m.id==='ff-squad'?'100':'10';return `<article class="tn-card tn-${g.className}"><a class="tn-card-top tn-banner-${theme}${banners[m.id]?' tn-card-image-banner':''}" href="#/tournaments/${m.id}">${banners[m.id]?`<img class="tn-supplied-banner" src="assets/tournaments/${banners[m.id]}" alt="${g.name} tournament banner" width="1920" height="720" loading="lazy">`: '<span class="tn-banner-placeholder"></span>'}<span class="tn-banner-art tn-banner-art-${m.game}" aria-hidden="true"><img src="assets/tournaments/characters.png" alt="" loading="lazy" width="1254" height="1254"></span>${gameLogo(m.game)}<div class="tn-banner-boost"><span>WIN</span><strong>${boost}<em>X</em></strong></div><span class="tn-sample">COMING SOON</span><div class="tn-card-title"><span>${g.name}</span><h3>${m.title}</h3><p>${m.mode} <i>•</i> ${m.format}</p></div><span class="tn-card-number" aria-hidden="true">${m.mode==='Squad'?'04':'01'}</span></a><div class="tn-card-body"><div class="tn-card-meta"><div>${trophy}<span>Prize pool<strong>Announcing soon</strong></span></div><div><span class="tn-entry-icon" aria-hidden="true">◇</span><span>Entry fee<strong>To be announced</strong></span></div><div class="tn-timing"><span>Timing<strong>Coming soon</strong></span></div></div><a class="tn-details" href="#/tournaments/${m.id}">Registration ${arrow}</a></div></article>`;}
  function list(game='all',status='upcoming'){if(live()){if(!liveData)return '<div class="tn-empty"><p>Loading tournaments…</p></div>';const wanted={upcoming:'open',live:'live',completed:'completed'}[status];const rows=liveData.tournaments.filter(m=>!m.deleted_at&&m.game==='ff'&&(game==='all'||m.game===game)&&(status==='registered'?liveData.entries.some(e=>e.tournament_id===m.id&&e.status!=='cancelled'):m.status===wanted));return rows.length?rows.map(managedCard).join(''):'<div class="tn-empty"><img class="cw-no-data-art" src="assets/no-data.svg" alt="" aria-hidden="true"><h3>No '+status+' matches yet</h3><p>New tournaments will appear here when announced.</p></div>';}const rows=matches.filter(m=>game==='all'?m.game==='ff':m.game===game);return status==='upcoming'?rows.map(card).join(''):`<div class="tn-empty"><img class="cw-no-data-art" src="assets/no-data.svg" alt="" aria-hidden="true"><h3>${status==='registered'?'No registered matches yet':status==='live'?'No live matches yet':'No completed matches yet'}</h3><p>${status==='live'?'Check Upcoming for the next arenas.':'Results will appear here after matches finish.'}</p></div>`;}
  function home(){return `${header('Tournaments')}<section class="tn-hero tn-master-banner"><img src="assets/tournaments/master-banner.png" alt="Color Win Tournaments — Free Fire and BGMI. Play, compete, win." width="1672" height="941" fetchpriority="high"></section><main class="tn-content"><div class="tn-section-heading"><div><span>CHOOSE YOUR BATTLEGROUND</span><h2>Join &amp; Win</h2></div><button type="button" id="tn-rules" aria-label="How tournaments work">?</button></div><div class="tn-game-tabs" role="tablist" aria-label="Filter by game">${[['all','All games'],['ff','Free Fire'],['pubg','BGMI']].map(([id,label])=>`<button type="button" role="tab" data-tn-game="${id}" aria-selected="${id==='all'}">${label}</button>`).join('')}</div><div class="tn-status-tabs" role="tablist" aria-label="Match status">${[['upcoming','Upcoming'],['registered','Registered'],['live','Live'],['completed','Completed']].map(([id,label])=>`<button type="button" role="tab" data-tn-status="${id}" aria-selected="${id==='upcoming'}">${id==='live'?'<i></i>':''}${label}</button>`).join('')}</div><div class="tn-list" id="tn-list" role="tabpanel" aria-label="Matches">${list()}</div><a class="tn-my-banner" href="#/tournaments/my-matches">${trophy}<span><strong>Match history & rewards</strong><small>Played matches, results & reward status</small></span>${arrow}</a><p class="tn-launch-note">Match previews. Registration opens when the first tournaments are announced.</p></main><dialog class="tn-dialog" id="tn-pubg-dialog">${trophy}<h2>BGMI coming soon</h2><p>New BGMI tournaments are on the way. Stay tuned for the first matches.</p><button type="button" class="tn-primary" id="tn-pubg-close">Got it</button></dialog><dialog class="tn-dialog" id="tn-rules-dialog"><button type="button" aria-label="Close" id="tn-close">×</button>${trophy}<h2>Your arena, your team</h2><p>Choose Free Fire or PUBG and open a match to see its format. Entry fees, prize pools, schedules and tournament rules will be announced before registration opens.</p><p>Registered matches, room access and results will appear in My matches.</p><button type="button" class="tn-primary" id="tn-ok">Got it</button></dialog>`;}
  function detail(m){const g=games[m.game];return `${header('Match details','#/tournaments')}<section class="tn-detail-hero tn-${g.className}"><span class="tn-game-mark">${g.short}<small>${g.tag}</small></span><span class="tn-sample">COMING SOON</span><h2>${m.title}</h2><p>${m.mode} · ${m.format}</p></section><main class="tn-content"><section class="tn-detail-box"><h3>${trophy} Match overview</h3><dl>${[['Game',g.name],['Team format',m.mode],['Match type',m.format],['Prize pool','Announcing soon'],['Entry fee','To be announced'],['Start time','Schedule coming soon']].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl></section><section class="tn-detail-box"><h3>Room access</h3><p>Room ID and password will appear here for registered players when the match room opens.</p><div class="tn-room-locked"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/></svg>Available after registration</div></section><section class="tn-detail-box"><h3>Before you join</h3><p>The final match rules, scoring, eligibility and cancellation terms will be published with the schedule.</p></section><button type="button" class="tn-primary" disabled>Registration opens soon</button><a class="tn-back-link" href="#/tournaments">Explore other matches ${arrow}</a></main>`;}
  function view(route,tabbar=''){if(liveOwner!==window.ColorWinAuth?.session?.user?.id){liveOwner=window.ColorWinAuth?.session?.user?.id||'';liveData=null;liveAt=0;ownedStatus='upcoming';}let body;if(route==='#/tournaments/my-matches')body=header('Match history','#/tournaments')+'<main class="tn-content"><section class="tn-rewards-summary"><span>TOURNAMENT REWARDS</span><h2>Your rewards</h2><p>Rewards from completed matches will appear here after results are verified.</p><div><strong>No rewards yet</strong><span>0 played matches</span></div></section><div class="tn-empty"><img class="cw-no-data-art" src="assets/no-data.svg" alt="" aria-hidden="true"><h3>Your next match is waiting</h3><p>Your played matches, rank and reward status will appear here.</p><a class="tn-primary" href="#/tournaments">Explore tournaments</a></div></main>';else if(live()&&liveData?.tournaments.some(m=>route==='#/tournaments/'+m.id))body=managedDetail(liveData.tournaments.find(m=>route==='#/tournaments/'+m.id));else{const m=matches.find(m=>route==='#/tournaments/'+m.id);body=m?detail(m):home();}if(live()&&route==='#/tournaments/my-matches')body=managedHistory();return `<section class="tn-page" data-tn-route="${esc(route)}">${body}${tabbar}</section>`;}
  async function bind(){const page=document.querySelector('.tn-page');if(live()&&(!liveData||Date.now()-liveAt>30000)){const owner=window.ColorWinAuth.session.user.id;try{const d=await window.ColorWinOperations.rpc('colorwin_tournament',{p_action:'load'});if(!page.isConnected||owner!==window.ColorWinAuth.session?.user?.id)return;liveOwner=owner;liveData=d;liveAt=Date.now();window.dispatchEvent(new Event('hashchange'));return;}catch(err){if(page.isConnected){const main=page.querySelector('.tn-content');if(main)main.innerHTML='<div class="tn-empty"><p>'+esc(err.message)+'</p></div>';}return;}}bindOwned(page);let game='all',status='upcoming';const draw=()=>{page.querySelector('#tn-list').innerHTML=list(game,status);};page.addEventListener?.('click',e=>{if(e.target.closest('[data-tn-closed]')){e.preventDefault();window.toast?.('Registration closed',true);}});
    if(live()&&typeof setInterval==='function'){
      const owner=window.ColorWinAuth.session.user.id;let pending=false;
      const timer=setInterval(async()=>{
        if(!page.isConnected||window.ColorWinAuth.session?.user?.id!==owner){clearInterval(timer);return;}
        if(pending||document.hidden)return;pending=true;
        try{const d=await window.ColorWinOperations.rpc('colorwin_tournament',{p_action:'load'});if(!page.isConnected||window.ColorWinAuth.session?.user?.id!==owner)return;liveData=d;liveAt=Date.now();const owned=page.querySelector('#tn-owned-list');if(owned)owned.innerHTML=ownedList();if(page.querySelector('#tn-list'))draw();else{const m=d.tournaments.find(x=>'#/tournaments/'+x.id===page.dataset.tnRoute);if(m){page.querySelectorAll('[data-tn-room]').forEach(b=>{if(!b.dataset.roomOpening)b.disabled=m.status!=='live';});page.querySelectorAll('[data-joining]').forEach(el=>el.outerHTML=joiningStatus(m));const form=page.querySelector('#tn-join');if(form&&!registrationOpen(m)){form.outerHTML='<div class="tn-empty">Registration closed</div>';window.toast?.('Registration closed',true);}}}}catch{}finally{pending=false;}
      },5000);
    }
page.querySelectorAll('[data-tn-game]').forEach(b=>b.onclick=()=>{if(b.dataset.tnGame==='pubg'){page.querySelector('#tn-pubg-dialog')?.showModal();return;}game=b.dataset.tnGame;page.querySelectorAll('[data-tn-game]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));draw();});page.querySelectorAll('[data-tn-status]').forEach(b=>b.onclick=()=>{status=b.dataset.tnStatus;page.querySelectorAll('[data-tn-status]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));draw();});const pubgDialog=page.querySelector('#tn-pubg-dialog');page.querySelector('#tn-pubg-close')?.addEventListener('click',()=>pubgDialog.close());const dialog=page.querySelector('#tn-rules-dialog');page.querySelector('#tn-rules')?.addEventListener('click',()=>dialog.showModal());page.querySelectorAll('#tn-close,#tn-ok').forEach(b=>b.onclick=()=>dialog.close());page.querySelector('#tn-join')?.addEventListener('submit',e=>registerMatch(e,page));page.querySelectorAll('[data-tn-room]').forEach(b=>b.onclick=async()=>{if(b.disabled)return;b.dataset.roomOpening='true';b.disabled=true;try{const r=await window.ColorWinOperations.rpc('colorwin_tournament',{p_action:'room',p_data:{id:b.dataset.tnRoom}});if(!page.isConnected)return;const note=b.parentElement.querySelector('[role=status]');if(r.room_link){const url=new URL(r.room_link);if(url.protocol!=='https:'||url.username||url.password)throw Error('Invalid room invite link.');note.textContent='Opening your match room…';window.location.assign(url.href);}else{note.textContent=r.room_id?'Room: '+r.room_id+' · Password: '+r.password:'Room invite link not published yet.';}}catch(err){b.parentElement.querySelector('[role=status]').textContent=err.message;}finally{delete b.dataset.roomOpening;b.disabled=liveData?.tournaments.find(m=>m.id===b.dataset.tnRoom)?.status!=='live';}});return loadWallet(page);}

  async function registerMatch(event,page){
    event.preventDefault();const form=event.currentTarget,button=form.querySelector('button');if(button.disabled)return;
    const owner=window.ColorWinAuth.session?.user?.id,route=page.dataset.tnRoute,id=route.split('/')[2];button.disabled=true;
    try{
      const entry=await window.ColorWinOperations.rpc('colorwin_tournament',{p_action:'join',p_data:{id,player_id:form.elements.player_id.value,player_name:(String(window.ColorWinAuth?.profile?.display_name||'').trim().slice(0,40)||'Player '+String(window.ColorWinAuth?.profile?.public_uid||''))}});
      if(owner!==window.ColorWinAuth.session?.user?.id)return;
      if(liveData){const alreadyJoined=liveData.entries.some(e=>e.tournament_id===id);liveData.entries=liveData.entries.filter(e=>e.tournament_id!==id);liveData.entries.push({...entry,tournament_id:id});const match=liveData.tournaments.find(m=>m.id===id);if(match&&!alreadyJoined)match.joined_count=Number(match.joined_count||0)+1;liveAt=Date.now();}
      try{await window.ColorWinAccount?.refreshBalance?.();}catch{}
      if(owner!==window.ColorWinAuth.session?.user?.id)return;
      if(page.isConnected&&location.hash===route)window.dispatchEvent(new Event('hashchange'));
      window.toast?.('Registration confirmed',false,4500);
    }catch(err){if(page.isConnected&&owner===window.ColorWinAuth.session?.user?.id){form.querySelector('[role=alert]').textContent=err.message;window.toast?.(err.message,true);button.disabled=false;}}
  }
  const rupees=v=>'₹'+Number(v).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
  const registrationOpen=m=>m.status==='open'&&!m.registration_closed&&Number(m.joined_count||0)<Number(m.capacity);
  const joiningStatus=m=>'<span class="tn-joining-status" data-joining="'+esc(m.id)+'"><i></i>'+Number(m.joined_count||0)+'/'+Number(m.capacity)+' joined</span>';
  function managedCard(m){const joined=liveData.entries.some(e=>e.tournament_id===m.id&&e.status!=='cancelled');return '<article class="tn-card tn-'+m.game+'"><a class="tn-card-top tn-card-image-banner" href="#/tournaments/'+m.id+'"><img class="tn-supplied-banner" src="'+esc(m.banner)+'" alt="'+esc(m.title)+'" loading="lazy"><div class="tn-card-title"><h3>'+esc(m.title)+'</h3><p>'+esc(m.mode)+' · '+esc(m.status)+'</p></div></a><div class="tn-card-body"><div class="tn-match-name"><h3>'+esc(m.title)+'</h3>'+(joined?'<span>Registered</span>':'')+'</div><div class="tn-card-meta"><div>'+trophy+'<span>Prize pool<strong>'+rupees(m.prize_pool)+'</strong></span></div><div><span>Entry fee<strong>'+rupees(m.entry_fee)+'</strong></span></div><div class="tn-timing"><span>Timing<strong>'+matchTime(m.starts_at)+'</strong>'+joiningStatus(m)+'</span></div></div><a class="tn-details" '+(joined||registrationOpen(m)?'':'data-tn-closed ' )+'href="#/tournaments/'+m.id+'">'+(joined?'Open my match':registrationOpen(m)?'Register now':'Registration closed')+' '+arrow+'</a></div></article>';}
  const matchTime=value=>{const d=new Date(value);return Number.isNaN(d.getTime())?'To be announced':esc(d.toLocaleDateString('en-IN',{timeZone:'Asia/Kolkata',day:'numeric',month:'short'}))+' '+esc(d.toLocaleTimeString('en-IN',{timeZone:'Asia/Kolkata',hour:'numeric',minute:'2-digit',hour12:true}));};
  function managedDetail(m){
    const joined=liveData.entries.some(e=>e.tournament_id===m.id&&e.status!='cancelled'),uid=window.ColorWinAuth?.profile?.public_uid;
    const registration=joined?'<section class="tn-detail-box"><h3>You are registered</h3><button class="tn-primary" data-tn-room="'+m.id+'"'+(m.status==='live'?'': ' disabled')+'>JOIN MATCH</button><p role="status">Room access opens when the admin starts the match.</p></section>':registrationOpen(m)&&m.game==='ff'?'<form id="tn-join" class="tn-detail-box"><h3>Register for '+rupees(m.entry_fee)+'</h3><p>Entry fee is deducted from your wallet when registration succeeds.</p><label>Color Win UID<input name="colorwin_uid" value="'+esc(uid||'Unavailable')+'" readonly aria-readonly="true"></label><small class="tn-registration-note">Verified results are rewarded to this Color Win account.</small><label>Free Fire game UID<input name="player_id" required pattern="[0-9]{5,20}" inputmode="numeric" placeholder="Enter your Free Fire UID"></label><button class="tn-primary" type="submit">Confirm registration</button><p role="alert"></p></form>':'<div class="tn-empty">Registration closed'+(Number(m.joined_count||0)>=Number(m.capacity)?' · All slots filled':'')+'</div>';
    return header('Match details','#/tournaments')+'<main class="tn-content">'+managedCard(m)+registration+'<section class="tn-detail-box"><h3>Match rules</h3><p style="white-space:pre-wrap">'+esc(m.rules||'Rules will be published before the match.')+'</p><p>'+m.capacity+' slots · '+esc(m.mode)+'</p></section></main>';
  }
  function ownedList(){
    if(!liveData)return '<p class="tn-empty">Loading your matches…</p>';
    const rows=liveData.entries.map(e=>({e,m:liveData.tournaments.find(m=>m.id===e.tournament_id)})).filter(({e,m})=>m&&e.status!=='cancelled'&&(ownedStatus==='upcoming'?m.status==='open':ownedStatus==='live'?m.status==='live':m.status==='completed'));
    return rows.length?rows.map(({e,m})=>'<article class="tn-owned-card"><img src="'+esc(m.banner)+'" alt="" loading="lazy"><div><span class="tn-owned-state">'+(ownedStatus==='live'?'LIVE · REGISTERED':ownedStatus==='completed'?'COMPLETED':'REGISTERED · UPCOMING')+'</span><h3>'+esc(m.title)+'</h3><p>'+matchTime(m.starts_at)+' · '+esc(m.mode)+'</p><p>'+(ownedStatus==='completed'?'Rank: '+esc(e.rank||'Awaiting result')+' · '+(e.reward_paid_at?'Reward '+rupees(e.reward):'Reward pending')+(e.most_kills_paid_at?' · Most kills '+rupees(e.most_kills_reward):''):'Game UID: '+esc(e.player_id||''))+'</p><a class="tn-primary" href="#/tournaments/'+m.id+'">'+(ownedStatus==='live'?'Open live match':ownedStatus==='completed'?'View result':'Open my match')+'</a></div></article>').join(''):'<div class="tn-owned-empty"><img class="cw-no-data-art" src="assets/no-data.svg" alt="" aria-hidden="true">'+(ownedStatus==='upcoming'?'Your registered upcoming matches will appear here.':ownedStatus==='live'?'Your joined matches will appear here when the admin starts them.':'Your completed matches and rewards will appear here.')+'</div>';
  }
  function ownedPanel(){return '<section class="tn-owned-panel"><div class="tn-owned-heading"><h2>My registered matches</h2><span>YOUR ARENA</span></div><div class="tn-owned-tabs" role="tablist" aria-label="My match status">'+[['upcoming','Upcoming'],['live','Joined Live'],['completed','Completed']].map(([id,label])=>'<button type="button" role="tab" data-owned-status="'+id+'" aria-selected="'+(ownedStatus===id)+'">'+label+'</button>').join('')+'</div><div id="tn-owned-list" role="tabpanel">'+ownedList()+'</div></section>';}
  function bindOwned(page){page.addEventListener?.('click',e=>{const b=e.target.closest('[data-owned-status]');if(!b)return;ownedStatus=b.dataset.ownedStatus;page.querySelectorAll('[data-owned-status]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));page.querySelector('#tn-owned-list').innerHTML=ownedList();});}
  function managedHistory(){const total=(liveData?.entries||[]).reduce((n,e)=>n+(Number(e.reward_paid_at?e.reward:0)+Number(e.most_kills_paid_at?e.most_kills_reward:0)),0);return header('My matches','#/tournaments')+'<main class="tn-content">'+ownedPanel()+'<section class="tn-rewards-summary"><span>TOURNAMENT REWARDS</span><h2>'+rupees(total)+'</h2><p>Credited after the admin verifies your result.</p></section></main>';}


  window.ColorWinTournaments={matches:r=>/^#\/tournaments\/[0-9a-f-]{36}$/.test(r)||r==='#/tournaments'||r==='#/tournaments/my-matches'||matches.some(m=>r==='#/tournaments/'+m.id),view,bind,list,events:matches};
})();
